import{_ as t,a as i}from"./chunks/git_github_2.d-LBDz3k.js";import{_ as o}from"./chunks/git_10.CsbTCZXu.js";import{_ as r,a as s,b as n,c as a}from"./chunks/git_16.G7SmDmQB.js";import{_ as u,c as l,o as c,ag as p}from"./chunks/framework.BtwP-r-R.js";const d="/14B-POO-A26/assets/git_github_3.Dv_CNS54.png",g="/14B-POO-A26/assets/git_gitignore.TAVMT_Cv.png",S=JSON.parse('{"title":"Git avec Visual Studio et GitHub  Collaboration en équipe","description":"","frontmatter":{},"headers":[],"relativePath":"git_github_equipe.md","filePath":"git_github_equipe.md"}'),m={name:"git_github_equipe.md"};function f(v,e,h,q,_,b){return c(),l("div",null,[...e[0]||(e[0]=[p('<h1 id="git-avec-visual-studio-et-github-collaboration-en-equipe" tabindex="-1">Git avec Visual Studio et GitHub <br><small> Collaboration en équipe </small> <a class="header-anchor" href="#git-avec-visual-studio-et-github-collaboration-en-equipe" aria-label="Permalink to &quot;Git avec Visual Studio et GitHub &lt;br&gt;&lt;small&gt; Collaboration en équipe &lt;/small&gt;&quot;">​</a></h1><p>Dans le cadre d&#39;un développement logiciel, le travail d&#39;équipe nécessite une coordination rigoureuse pour éviter que les modifications des uns n&#39;écrasent le travail des autres. Les étapes suivantes vous montrent comment effectuer la configuration initiale de votre dépôt, appliquer les bonnes pratiques de synchronisation (Pull avant Push), et résoudre sereinement les conflits de code qui peuvent survenir en cours de route.</p><h2 id="configuration-initiale-pour-une-equipe-travaillant-sur-un-meme-projet" tabindex="-1">Configuration initiale pour une équipe travaillant sur un même projet <a class="header-anchor" href="#configuration-initiale-pour-une-equipe-travaillant-sur-un-meme-projet" aria-label="Permalink to &quot;Configuration initiale pour une équipe travaillant sur un même projet&quot;">​</a></h2><ol><li><p><strong>Coéquipier 1</strong> : Celui ayant une version à jour du projet</p><ol><li>Ouvrir le projet Visual Studio existant et sélectionnier le menu <code>Git--&gt; créer un dépôt Git</code></li></ol><p><img src="'+t+'" alt="Nouveau projet github"></p><ol start="2"><li><p>Séctionner le modèle .gitignore par défaut de Visual Studio</p></li><li><p>Se connecter à son compte GitHub, indiquer le nom du dépôt et cocher la case &quot;Dépôt privé&quot;</p></li></ol><p><img src="'+i+'" alt="Nouveau projet github"></p><ol start="4"><li><p>Cliquer sur le bouton <code>Créer et envoyer (push)</code></p></li><li><p>Sur le site de GitHub, sélectionner votre projet et cliquer sur le menu <code>Settings</code>, cliquer sur l&#39;option <code>Collaborators</code>, cliquer sur le bouton <code>Add people</code> et ajouter votre coéquiper.</p></li></ol><p><img src="'+d+'" alt="Nouveau projet github"></p></li></ol><h2 id="gitignore-ignorer-des-fichier-pour-un-depot-distant-clone-qui-n-en-contient-pas" tabindex="-1">.gitignore : Ignorer des fichier - Pour un dépôt distant cloné qui n&#39;en contient pas <a class="header-anchor" href="#gitignore-ignorer-des-fichier-pour-un-depot-distant-clone-qui-n-en-contient-pas" aria-label="Permalink to &quot;.gitignore : Ignorer des fichier - Pour un dépôt distant cloné qui n&#39;en contient pas&quot;">​</a></h2><p>Pour ignorer certains fichiers de votre solution afin qu&#39;ils ne soient pas publiés sur le dépôt distant et ainsi éviter des conflits, vous devez utiliser un fichier nommé « .gitignore » . Si vous ne l&#39;avez pas fait lors de la création du dépôt, voici comment faire.</p><p>Vous devez :</p><ol><li>Cliquer sur l&#39;option « <strong>…</strong> » à partir du menu « <strong>Gérer les dépôt distants …</strong> ».</li></ol><p><img src="'+o+'" alt="Nouveau projet git la"></p><ol start="2"><li>Vous devez par la suite sélectionner dans le menu, l&#39;option <strong>Paramètres Git -&gt; Configuration du référentiel Git</strong>. Cliquer sur le bouton « <strong>Ajouter /.gitignore</strong> » :</li></ol><p><img src="'+g+'" alt="Nouveau projet git la"></p><h2 id="comment-faire-pour-accepter-une-version-modifiee-de-certains-fichiers-et-les-mettre-sur-le-depot-distant" tabindex="-1">Comment faire pour accepter une version modifiée de certains fichiers et les mettre sur le dépôt distant ? <a class="header-anchor" href="#comment-faire-pour-accepter-une-version-modifiee-de-certains-fichiers-et-les-mettre-sur-le-depot-distant" aria-label="Permalink to &quot;Comment faire pour accepter une version modifiée de certains fichiers et les mettre sur le dépôt distant ?&quot;">​</a></h2><p>Important : Avant de pouvoir effectuer un « <strong>Push</strong> », vous devez avoir une copie à jour des fichiers du dépôt distant. Ainsi, il est préférable, <strong>voire nécessaire, de toujours faire un « Pull » avant un « Push »</strong>.</p><ul><li>Exécutez les commandes suivantes dans cet ordre : <ul><li>À partir de l&#39;onglet « Modification Git», saisissez le texte du &quot;Commit&quot; (celui-ci doit être significatif) et cliquez sur « <strong>Valider tout et synchroniser</strong> ».</li><li>Éventuellement, vous devrez gérer manuellement les conflits si la version locale d’un fichier est différente de celle sur le dépôt distant.</li><li>S’il n’y a aucun conflit, alors cliquez sur le lien « <strong>Pousser</strong> ».</li></ul></li></ul><h2 id="comment-resoudre-des-conflits" tabindex="-1">Comment résoudre des conflits <a class="header-anchor" href="#comment-resoudre-des-conflits" aria-label="Permalink to &quot;Comment résoudre des conflits&quot;">​</a></h2><p>Lorsque vous tentez de pousser vos modifications sur le dépôt distant, il se peut que le message suivant s&#39;affiche :</p><p><img src="'+r+'" alt="Message de conflit"></p><p>Cela indique que votre version du code n&#39;est pas à jour par rapport à celle se trouvant sur le dépôt distant. <strong>Vous devez donc synchroniser votre code en tirant celui qui se trouve sur le dépôt distant</strong>.</p><p>Lors d’une synchronisation, il se peut que vous ayez des conflits à résoudre avant de pouvoir pousser votre code :</p><p><img src="'+s+'" alt="Message de conflit"></p><p>Dans ce cas, cliquez sur le lien « <strong>Ouvrir l&#39;éditeur de fusion</strong> ». La fenêtre suivante affichera les conflits :</p><p><img src="'+n+'" alt="Message de conflit"></p><p>Vous n’aurez qu’à cocher le code du côté distant ou local que vous désirez conserver et celui-ci apparaîtra dans la section du bas. Une fois terminé, cliquez sur le bouton « <strong>Accepter la fusion</strong> ».</p><p><img src="'+a+'" alt="Message de conflit"></p><p>À partir de la fenêtre « <strong>Modifications Git</strong> », saisissez le texte du &quot;Commit&quot; (celui-ci doit être significatif) et cliquez sur « <strong>Valider les changements pousser</strong>».</p>',25)])])}const G=u(m,[["render",f]]);export{S as __pageData,G as default};
